using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Text.Json;

namespace McpServer;

[McpServerToolType]
public sealed class ApiFetchTool
{
    private readonly IHttpClientFactory _httpClientFactory;

    public ApiFetchTool(IHttpClientFactory httpClientFactory)
    {
        _httpClientFactory = httpClientFactory;
    }

    [McpServerTool("fetch_api_data"),
     Description("Fetches data from an external API endpoint and returns the JSON response.")]
    public async Task<string> FetchApiDataAsync(
        [Description("The relative path to fetch (e.g. \"/users/1\").")] string path,
        CancellationToken cancellationToken = default)
    {
        using var client = _httpClientFactory.CreateClient("ExternalApi");

        using var response = await client.GetAsync(path, cancellationToken);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadAsStringAsync(cancellationToken);

        // Re-serialize to ensure valid, indented JSON is returned.
        var doc = JsonSerializer.Deserialize<JsonElement>(json);
        return JsonSerializer.Serialize(doc, new JsonSerializerOptions { WriteIndented = true });
    }
}

using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpServer;

[McpServerPromptType]
public sealed class SummarizePrompt
{
    [McpServerPrompt("summarize"),
     Description("Generates a prompt that asks an LLM to summarize the provided text.")]
    public static IList<PromptMessage> Summarize(
        [Description("The text content to summarize.")] string text,
        [Description("Maximum number of sentences for the summary (default: 3).")] int maxSentences = 3)
    {
        return
        [
            new PromptMessage
            {
                Role = Role.User,
                Content = new Content
                {
                    Type = "text",
                    Text = $"""
                        Please summarize the following text in at most {maxSentences} sentence(s).
                        Be concise and capture the key points.

                        ---
                        {text}
                        ---
                        """
                }
            }
        ];
    }
}

